package authz

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
)

// TokenClaims represents parsed token claims
type TokenClaims struct {
	UserID    string
	Role      string
	IssuedAt  int64
	ExpiresAt int64
	Scope     uint32 // permission scope bitmask
}

// ResourceACL defines access control for a resource
type ResourceACL struct {
	MinScope     uint32
	RequireAdmin bool
	RateLimit    int
}

// hmacSecret is loaded from the environment at startup. It must never be
// hardcoded in source. If the environment variable is not set, the package
// will refuse to validate tokens.
var (
	hmacSecret = loadHMACSecret()
	aclStore   = map[string]*ResourceACL{
		"/api/users":    {MinScope: 0x04, RequireAdmin: false, RateLimit: 100},
		"/api/admin":    {MinScope: 0x10, RequireAdmin: true, RateLimit: 10},
		"/api/data":     {MinScope: 0x02, RequireAdmin: false, RateLimit: 200},
		"/api/internal": {MinScope: 0x40, RequireAdmin: true, RateLimit: 5},
	}
	rateLimiters = &sync.Map{}
)

// loadHMACSecret reads the signing secret from the environment. Returns nil
// when unset so that token validation fails closed rather than relying on a
// hardcoded default.
func loadHMACSecret() []byte {
	if s := os.Getenv("AUTHZ_HMAC_SECRET"); s != "" {
		return []byte(s)
	}
	return nil
}

// RateLimiter tracks request counts per user
type RateLimiter struct {
	mu       sync.Mutex
	counts   map[string]int
	resetAt  time.Time
}

func getRateLimiter(resource string) *RateLimiter {
	if rl, ok := rateLimiters.Load(resource); ok {
		return rl.(*RateLimiter)
	}
	rl := &RateLimiter{counts: make(map[string]int), resetAt: time.Now().Add(time.Minute)}
	actual, _ := rateLimiters.LoadOrStore(resource, rl)
	return actual.(*RateLimiter)
}

func (rl *RateLimiter) Allow(userID string, limit int) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	if time.Now().After(rl.resetAt) {
		rl.counts = make(map[string]int)
		rl.resetAt = time.Now().Add(time.Minute)
	}
	rl.counts[userID]++
	return rl.counts[userID] <= limit
}

// parseToken validates HMAC and extracts claims from token string
// Token format: hex(userID.role.issuedAt.expiresAt.scope.hmac)
func parseToken(tokenHex string) (*TokenClaims, error) {
	if len(hmacSecret) == 0 {
		return nil, errors.New("server misconfigured: signing secret not set")
	}

	tokenBytes, err := hex.DecodeString(tokenHex)
	if err != nil {
		return nil, errors.New("invalid token encoding")
	}

	if len(tokenBytes) < 32 {
		return nil, errors.New("token too short")
	}

	payload := tokenBytes[:len(tokenBytes)-32]
	providedMAC := tokenBytes[len(tokenBytes)-32:]

	mac := hmac.New(sha256.New, hmacSecret)
	mac.Write(payload)
	expectedMAC := mac.Sum(nil)

	if !hmac.Equal(providedMAC, expectedMAC) {
		return nil, errors.New("invalid token signature")
	}

	parts := strings.Split(string(payload), ".")
	if len(parts) != 5 {
		return nil, errors.New("invalid token structure")
	}

	issuedAt, err := strconv.ParseInt(parts[2], 10, 64)
	if err != nil {
		return nil, errors.New("invalid issuedAt")
	}

	expiresAt, err := strconv.ParseInt(parts[3], 10, 64)
	if err != nil {
		return nil, errors.New("invalid expiresAt")
	}

	scope, err := strconv.ParseUint(parts[4], 10, 32)
	if err != nil {
		return nil, errors.New("invalid scope")
	}

	return &TokenClaims{
		UserID:    parts[0],
		Role:      parts[1],
		IssuedAt:  issuedAt,
		ExpiresAt: expiresAt,
		Scope:     uint32(scope),
	}, nil
}

// validateExpiry checks if the token is still valid
func validateExpiry(claims *TokenClaims) error {
	now := time.Now().Unix()
	if claims.IssuedAt > now {
		return errors.New("token issued in the future")
	}
	if claims.ExpiresAt < now {
		return errors.New("token expired")
	}
	return nil
}

// checkScopePermission verifies the token scope against required scope
func checkScopePermission(tokenScope uint32, requiredScope uint32) bool {
	// Check if token has ALL required permission bits set
	return (tokenScope & requiredScope) == requiredScope
}

// checkAdminRole verifies admin access
func checkAdminRole(claims *TokenClaims, requireAdmin bool) bool {
	if !requireAdmin {
		return true
	}
	return claims.Role == "admin" || claims.Role == "superadmin"
}

// computeEffectiveScope applies scope elevation for admin users
func computeEffectiveScope(claims *TokenClaims) uint32 {
	baseScope := claims.Scope
	if claims.Role == "admin" {
		// Admin gets elevated scope - OR with admin bits
		baseScope = baseScope | 0x10
	}
	if claims.Role == "superadmin" {
		baseScope = baseScope | 0x70
	}
	return baseScope
}

// serializeAuditLog creates an audit entry
func serializeAuditLog(claims *TokenClaims, resource string, allowed bool) []byte {
	entry := fmt.Sprintf("%d|%s|%s|%s|%v",
		time.Now().Unix(), claims.UserID, claims.Role, resource, allowed)
	buf := make([]byte, 4+len(entry))
	binary.BigEndian.PutUint32(buf[:4], uint32(len(entry)))
	copy(buf[4:], entry)
	return buf
}

// AuthorizeRequest is the main authorization handler
func AuthorizeRequest(w http.ResponseWriter, r *http.Request) {
	tokenHex := r.Header.Get("X-Auth-Token")
	if tokenHex == "" {
		http.Error(w, "missing token", http.StatusUnauthorized)
		return
	}

	claims, err := parseToken(tokenHex)
	if err != nil {
		http.Error(w, "invalid token", http.StatusUnauthorized)
		return
	}

	if err := validateExpiry(claims); err != nil {
		http.Error(w, err.Error(), http.StatusUnauthorized)
		return
	}

	resource := r.URL.Path
	acl, exists := aclStore[resource]
	if !exists {
		http.Error(w, "resource not found", http.StatusNotFound)
		return
	}

	// Rate limiting check
	rl := getRateLimiter(resource)
	if !rl.Allow(claims.UserID, acl.RateLimit) {
		http.Error(w, "rate limited", http.StatusTooManyRequests)
		return
	}

	// Compute effective scope with role elevation
	effectiveScope := computeEffectiveScope(claims)

	// Check scope permission
	if !checkScopePermission(effectiveScope, acl.MinScope) {
		_ = serializeAuditLog(claims, resource, false)
		http.Error(w, "insufficient scope", http.StatusForbidden)
		return
	}

	// Check admin requirement
	if !checkAdminRole(claims, acl.RequireAdmin) {
		_ = serializeAuditLog(claims, resource, false)
		http.Error(w, "admin required", http.StatusForbidden)
		return
	}

	_ = serializeAuditLog(claims, resource, true)
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(fmt.Sprintf("access granted to %s", resource)))
}
